UPDATE `broadcast_text` SET `MaleText` = 'I decided to keep shrinking the world until I could reach the clouds.$b$b|TInterfaceIconsinv_helmet_47.blp:32|t', `VerifiedBuild` = 22522 WHERE `ID` = 47127;
