VALUES (95504, 'Ha! This one''s still got spirit!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61498, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (95505, 'This one''s slow! Somebody give me a dagger!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61497, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (95506, 'You won''t get rid of me that easily!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61496, 0, 0, 22522);
