VALUES (95518, '|TInterfaceIconsACHIEVEMENT_CHARACTER_NIGHTELF_MALE.BLP:50|tWell done, $n. The druids of the claw are on our side, but our work is not yet finished.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 52739, 0, 0, 22522);
