VALUES (97233, 'What''s that you have there? A shiny weapon?', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52627, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (97234, 'You''ll make for a fatty meal.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52630, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (97235, 'Great kraken take you!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52628, 0, 0, 22522);
