VALUES (97237, 'You''re not from the ship!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52635, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (97238, 'I''ll chop you up into chum.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52636, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (97239, 'Over here! Invaders!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52633, 0, 0, 22522);
