VALUES (97965, 'Welcome to the Nightmare!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52092, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (97966, 'Your boldness will not save you this day!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52093, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (97967, 'Thaon you fool! You''ve already lost...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52094, 0, 0, 22522);
