VALUES (98085, 'I will feast in the High Halls!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52467, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98086, 'Die with honor, outsider!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52465, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98087, 'I die... historic...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52464, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98088, 'Gods... deem me worthy...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52463, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98089, 'Death is its own victory...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52462, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98090, 'Odyn, ready your halls...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52461, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98091, 'This land is doomed!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61449, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98092, 'Your resistance is futile!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61450, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98093, 'You do not see, but you will.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61451, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98094, 'You were warned.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61452, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98095, 'You cannot escape!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52491, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98096, 'Will the night elves mourn you, I wonder?', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61454, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98097, 'You will never leave!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52490, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98098, 'Looking for a fight? Allow me...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61455, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98099, 'Your corpse is another gift for Helya!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52489, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98100, 'Pity. You could have joined us...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61456, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98101, 'You would die for this pathetic land?', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 61457, 0, 40029, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98102, 'I will wear your bones!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52497, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98103, 'Drown in agony!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52496, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98104, 'The mists take you!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52495, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98105, 'I return to the mists...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52499, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98106, 'Helya, take me...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52494, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98107, 'Is the curse... ended?', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52493, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98108, 'My war... is eternal...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52492, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98109, 'You will serve willingly, or in chains!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52403, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98110, 'The high halls will burn!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52401, 0, 0, 22522);
