VALUES (98111, 'I will break you against the gates!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52402, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98112, 'You have not begun to know destruction!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52412, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (98113, 'The earth will shatter at the Legion''s coming!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 52411, 0, 0, 22522);
