VALUES (99652, 'Impressive you have made it this far, demon hunters. Now, I will extinguish your souls like a candle''s flame!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 57362, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (99653, 'We''ve done it, Illidari! FREEDOM IS OURS!', '', 396, 0, 0, 0, 0, 0, 603, 0, 0, 57363, 0, 0, 22522);
