VALUES (100767, 'Take your place among the circle, Farseer. The Earthen Ring is forged anew, and with it, we rekindle hope for this world.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 60716, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (100768, 'You are the chosen defender of Azeroth! May your wisdom guide this circle to victory, and may the power of the weapon you wield crush those who would bring chaos to this land.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 60717, 0, 0, 22522);
