VALUES (100796, 'Here, we live in peace away from the other drogbar.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 54778, 0, 36730, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (100797, 'Stonedark! I have returned! We have this one to thank for saving us from the Bloodtotem.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 54779, 0, 36730, 22522);
