VALUES (100807, '', 'The other survivors are up at the temple. If you''re feeling well, then you should head over there.', 0, 0, 0, 0, 0, 0, 0, 7, 0, 0, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (100808, 'Our people need a leader like Huln. One with the strength and courage to face any obstacle. Qualities you have proven to possess.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 54269, 0, 0, 22522);
