VALUES (101796, 'Light bless you, $n. Azeroth would be lost to the Legion if it weren''t for you.', 'Light bless you, $n. Azeroth would be lost to the Legion if it weren''t for you.', 0, 0, 0, 0, 0, 0, 66, 0, 0, 0, 0, 36948, 22522);
