VALUES (103014, 'I sense a powerful artifact hidden behind this wall. Tread carefully heroes, my father rarely left such prized possessions unguarded.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 54694, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (103015, 'That was easier than expected.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 54695, 0, 0, 22522);
