VALUES (105083, 'Listen! We don''t have much time. They took Margrave to the citadel. We''re gonna have to break in there to get ''im out!', '', 0, 0, 0, 0, 0, 0, 603, 0, 0, 60321, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (105084, 'Eliminate... all... life...', '', 0, 0, 0, 0, 0, 0, 463, 0, 0, 0, 0, 0, 22522);
