VALUES (105086, 'Good work! Now demonstrate your skill against two foes at the same time.', '', 0, 0, 0, 0, 0, 0, 21, 0, 0, 58006, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (105087, 'You learned well! Next we will see... Hold on, is that...? To arms! The Legion is attacking!', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 58007, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (105088, 'An infernal! Use all your training to defeat it!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58008, 0, 0, 22522);
