VALUES (105300, 'We''re here to slay a demon, not rescue every failure who couldn''t get the job done.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 60345, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (105301, 'I don''t care! Slaying the demon is our first priority. Come, we''ve wasted enough time with this blathering.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 60348, 0, 0, 22522);
