VALUES (107997, 'Such insolence... very well, I shall show you!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58431, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (107998, 'See for yourself the cruel, frozen void that lies beyond the margin of Azeroth''s skies!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58432, 0, 0, 22522);
