VALUES (108339, 'Emberscar has awakened and thirsts for souls. Defeat the Cinderweb Ambushers!', '', 0, 0, 0, 0, 0, 0, 0, 0, 17, 0, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (108340, 'The master has returned! We must ensure the household is immaculate.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58331, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (108341, 'That''s not the master, imbecile! Unless he managed to claw his way out from under two tons of solid stone.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58332, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (108342, 'Ooo, that would be impressive... considering I still have his hands in a jar.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58333, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (108343, 'Please don''t say such things! The master is back, and things need to be kept tidy.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58334, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (108344, 'You''re tracking mud everywhere!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 58335, 0, 0, 22522);
