VALUES (109053, 'Prove to me you have the necessary skill and cunning required to hunt any prey!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 59963, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (109054, 'Show me your courage and zeal in the heat of combat!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 59981, 0, 0, 22522);
