VALUES (109926, 'Cast Penance now!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 59902, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (109927, 'The power of the Light allows you to Smite any enemy that stands before you!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 59901, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (109928, 'Use Smite on the target dummy.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 59900, 0, 0, 22522);
