VALUES (111335, 'Breathtaking. Imagine all of the arcane knowledge lost to the ages here.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 60191, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (111336, 'There... the Illidari. And, the Burning Legion is here, too.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 60192, 0, 0, 22522);
