VALUES (116921, 'Walk in starlight.', 'Well''s gift be with you.', 0, 0, 0, 0, 0, 0, 0, 0, 0, 65841, 66040, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (116922, 'Your interference only delays the inevitable. Minions, destroy $g him:her;!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 70843, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (116923, 'Send in the wrathlords at once! Stop these meddling insects!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 70842, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (116924, 'You foolishly stand in defiance of the endless armies of Sargeras! Sisters, bring me $g his:her; head!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 70841, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (116925, 'For a prophet you are doing a very poor job of making predictions...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 70833, 0, 0, 22522);
