VALUES (119094, 'Greetings.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 67981, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (119095, 'Ours is a heavy burden.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 67982, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (119096, 'I see a great darkness looming over Netherlight Temple. The shadow of the Burning Legion, ready to strike.', '', 0, 0, 0, 0, 0, 0, 1, 0, 4, 68264, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (119097, 'Our order will fall at his hands, everyone within will perish.', '', 0, 0, 0, 0, 0, 0, 1, 0, 4, 68265, 0, 0, 22522);
