VALUES (119101, 'I see a path that leads to our victory! You are there, walking with the Light, guiding us all.', '', 0, 0, 0, 0, 0, 0, 1, 0, 4, 68268, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (119102, 'I know my path.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 67983, 0, 0, 22522);
