VALUES (120465, 'It would be foolish to think this attack will be the last, but we should take a moment to reflect on this victory and celebrate its true hero, our High Priest.', '', 0, 0, 0, 0, 0, 0, 1, 0, 0, 69376, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
