VALUES (120705, 'Check out this one - hand made in Kezan, hand stolen in Gadgetzan!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 69858, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (120706, 'Too late, too late will be the cry when Sixtrigger''s bargains pass you by!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 69857, 0, 0, 22522);
