VALUES (122152, 'You should be thankful that you were given this opportunity to serve!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 71358, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (122153, 'Some of you must die if our world is to survive!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 71359, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (122154, 'I am above your judgment! What I do, I do for Azeroth!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 71360, 0, 0, 22522);
INSERT INTO `broadcast_text` (`ID`, `MaleText`, `FemaleText`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `UnkEmoteID`, `Language`, `Type`, `SoundID1`, `SoundID2`, `PlayerConditionID`, `VerifiedBuild`)
VALUES (122155, 'The threat of the Legion costs lives. Your lives!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 71361, 0, 0, 22522);
